<?php require __DIR__.'/../config/bootstrap.php';require_role('student');$s=$pdo->prepare("SELECT c.*,e.enrolled_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? AND e.status='active' ORDER BY e.enrolled_at DESC");$s->execute([current_user()['id']]);$items=$s->fetchAll();$page_title='Student Dashboard';require __DIR__.'/../includes/header.php';?>
<h1 class="text-3xl font-bold">Welcome, <?= e(current_user()['full_name']) ?></h1><p class="text-slate-600 mt-2">Your learning dashboard.</p><div class="mt-7 flex justify-between items-center"><h2 class="text-xl font-bold">My courses</h2><a href="<?= BASE_URL ?>/courses.php" class="bg-blue-700 text-white px-4 py-2 rounded-lg">Browse courses</a></div><div class="grid md:grid-cols-2 gap-4 mt-4"><?php foreach($items as $c): ?><div class="bg-white border rounded-xl p-5"><h3 class="font-bold text-lg"><?= e($c['title']) ?></h3><p class="text-slate-600 mt-2"><?= e($c['description']) ?></p><span class="inline-block mt-4 text-green-700 text-sm font-semibold">Enrollment active</span></div><?php endforeach; ?><?php if(!$items): ?><div class="bg-white border rounded-xl p-6 text-slate-600">You have not enrolled in a course yet.</div><?php endif; ?></div><?php require __DIR__.'/../includes/footer.php';?>
